import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]): string {
  return twMerge(clsx(inputs));
}

"use client";

import * as React from "react";
import {
  motion,
  useMotionValue,
  useSpring,
  useTransform,
  useMotionTemplate,
  useReducedMotion,
} from "framer-motion";
import { cn } from "@/lib/utils";

export interface ParallaxTiltCard3DProps {
  children: React.ReactNode;
  /** Maximum tilt in degrees on each axis. */
  max?: number;
  /** CSS perspective (px). Higher = subtler. */
  perspective?: number;
  /** Toggle the moving glass glare overlay. */
  glare?: boolean;
  /** Glare intensity 0..1. */
  glareOpacity?: number;
  /** Spring stiffness — lower = more "breathing". */
  stiffness?: number;
  /** Spring damping. */
  damping?: number;
  className?: string;
}

/**
 * ParallaxTiltCard3D
 *
 * Cursor-tracked tilt with a Framer Motion spring on the rotation, plus a
 * glass glare layer that sweeps inversely to the tilt. Math is rooted at
 * the card's own bounding box (not the viewport), so the effect feels
 * locally anchored.
 *
 * GPU contract: only `transform` + `opacity` animate.
 */
export function ParallaxTiltCard3D({
  children,
  max = 14,
  perspective = 1100,
  glare = true,
  glareOpacity = 0.55,
  stiffness = 150,
  damping = 20,
  className,
}: ParallaxTiltCard3DProps) {
  const ref = React.useRef<HTMLDivElement>(null);
  const reduceMotion = useReducedMotion() ?? false;

  // Raw -1..1 normalized cursor position, springified for "breath".
  const px = useMotionValue(0);
  const py = useMotionValue(0);
  const sx = useSpring(px, { stiffness, damping, mass: 0.5 });
  const sy = useSpring(py, { stiffness, damping, mass: 0.5 });

  // Rotations.
  const rotateY = useTransform(sx, [-1, 1], [-max, max]);
  const rotateX = useTransform(sy, [-1, 1], [max, -max]);

  // Glare position — sweeps OPPOSITE to the tilt, like real reflected light.
  const glareX = useTransform(sx, [-1, 1], [85, 15]);
  const glareY = useTransform(sy, [-1, 1], [85, 15]);
  const glareO = useTransform(
    [sx, sy] as const,
    ([x, y]) => Math.min(1, Math.hypot(x as number, y as number)) * glareOpacity
  );
  const glareBg = useMotionTemplate`radial-gradient(600px circle at ${glareX}% ${glareY}%, rgba(255,255,255,0.85), rgba(255,255,255,0) 45%)`;

  function handleMove(e: React.PointerEvent<HTMLDivElement>) {
    if (reduceMotion) return;
    // Tilt only responds to a real mouse. Touch "taps" should not jolt the card.
    if (e.pointerType !== "mouse") return;
    const r = ref.current?.getBoundingClientRect();
    if (!r) return;
    const nx = ((e.clientX - r.left) / r.width) * 2 - 1;
    const ny = ((e.clientY - r.top) / r.height) * 2 - 1;
    px.set(Math.max(-1, Math.min(1, nx)));
    py.set(Math.max(-1, Math.min(1, ny)));
  }

  function handleLeave() {
    px.set(0);
    py.set(0);
  }

  return (
    <div
      ref={ref}
      onPointerMove={handleMove}
      onPointerLeave={handleLeave}
      className={cn("relative", className)}
      style={{ perspective: `${perspective}px` }}
    >
      <motion.div
        style={{
          rotateX: reduceMotion ? 0 : rotateX,
          rotateY: reduceMotion ? 0 : rotateY,
          transformStyle: "preserve-3d",
          willChange: reduceMotion ? "auto" : "transform",
        }}
        className="relative h-full w-full rounded-[inherit]"
      >
        {/* Card surface */}
        <div className="relative h-full w-full overflow-hidden rounded-[inherit]">
          {children}

          {glare && !reduceMotion && (
            <motion.div
              aria-hidden
              className="pointer-events-none absolute inset-0"
              style={{ background: glareBg, opacity: glareO, mixBlendMode: "soft-light" }}
            />
          )}
        </div>
      </motion.div>
    </div>
  );
}
